void CScenarioInfoDlg::UpdateAllyEnemyFlags()
{
    int localPlayer = gpGame->GetLocalPlayerGamePos();
    widget* flag;
    int i = 0;
    int nextEnemy = SCENARIO_INFO_ENEMY_FIRST_ID;
    int nextAlly = SCENARIO_INFO_ALLY_FIRST_ID;

    for (; i < 8; ++i) {
        flag = GetWidget(i + SCENARIO_INFO_ENEMY_FIRST_ID);
        flag->send_message(widget::WIDGET_CLEAR_STATUS,
                           widget::WIDGET_CLEAR_STATUS);
        flag = GetWidget(i + SCENARIO_INFO_ALLY_FIRST_ID);
        flag->send_message(widget::WIDGET_CLEAR_STATUS,
                           widget::WIDGET_CLEAR_STATUS);

        if (gpGame->setup.playerPos[i] >= 0) {
            if (gpGame->OnSameTeam(i, localPlayer)) {
                flag = GetWidget(nextAlly);
                flag->send_message(widget::WIDGET_SET_STATUS,
                                   widget::WIDGET_CLEAR_STATUS);
                GetWidget(nextAlly)->send_message(
                    widget::WIDGET_SET_ICON_FRAME, i);
                ++nextAlly;
            } else {
                flag = GetWidget(nextEnemy);
                flag->send_message(widget::WIDGET_SET_STATUS,
                                   widget::WIDGET_CLEAR_STATUS);
                GetWidget(nextEnemy)->send_message(
                    widget::WIDGET_SET_ICON_FRAME, i);
                ++nextEnemy;
            }
        }
    }
}

